  1→package kiro
  2→
  3→import (
  4→	"context"
  5→	"encoding/json"
  6→	"fmt"
  7→	"os"
  8→	"path/filepath"
  9→	"strings"
 10→
 11→	"github.com/entireio/cli/cmd/entire/cli/agent"
 12→	"github.com/entireio/cli/cmd/entire/cli/jsonutil"
 13→	"github.com/entireio/cli/cmd/entire/cli/paths"
 14→)
 15→
 16→// Ensure KiroAgent implements HookSupport
 17→var _ agent.HookSupport = (*KiroAgent)(nil)
 18→
 19→// HooksFileName is the config file for Kiro hooks.
 20→const HooksFileName = "entire.json"
 21→
 22→// hooksDir is the directory within .kiro where agent hook configs live.
 23→const hooksDir = "agents"
 24→
 25→// ideHooksDir is the directory within .kiro where IDE hook files live.
 26→const ideHooksDir = "hooks"
 27→
 28→// ideHookFileSuffix is the file extension for IDE hook files.
 29→const ideHookFileSuffix = ".kiro.hook"
 30→
 31→// ideHookVersion is the schema version for IDE hook files.
 32→const ideHookVersion = "1"
 33→
 34→// localDevCmdPrefix is the command prefix used for local development builds.
 35→const localDevCmdPrefix = "go run ${KIRO_PROJECT_DIR}/cmd/entire/main.go "
 36→
 37→// prodHookCmdPrefix is the command prefix for production hook commands.
 38→const prodHookCmdPrefix = "entire hooks kiro "
 39→
 40→// entireHookPrefixes identify Entire hooks in the config file.
 41→var entireHookPrefixes = []string{
 42→	"entire ",
 43→	localDevCmdPrefix,
 44→}
 45→
 46→// ideHookDef defines a single IDE hook file to install.
 47→type ideHookDef struct {
 48→	Filename    string // e.g. "entire-prompt-submit"
 49→	TriggerType string // e.g. "promptSubmit"
 50→	CLIVerb     string // e.g. "user-prompt-submit"
 51→}
 52→
 53→// ideHookDefs lists the 4 IDE hook files to install.
 54→// No agentSpawn IDE hook — the IDE has no such trigger.
 55→// The first promptSubmit serves as session start.
 56→var ideHookDefs = []ideHookDef{
 57→	{Filename: "entire-prompt-submit", TriggerType: "promptSubmit", CLIVerb: HookNameUserPromptSubmit},
 58→	{Filename: "entire-stop", TriggerType: "agentStop", CLIVerb: HookNameStop},
 59→	{Filename: "entire-pre-tool-use", TriggerType: "preToolUse", CLIVerb: HookNamePreToolUse},
 60→	{Filename: "entire-post-tool-use", TriggerType: "postToolUse", CLIVerb: HookNamePostToolUse},
 61→}
 62→
 63→// InstallHooks installs Entire hooks in .kiro/agents/entire.json (CLI hooks)
 64→// and .kiro/hooks/*.kiro.hook (IDE hooks).
 65→// Returns the total number of hooks installed (CLI + IDE).
 66→func (k *KiroAgent) InstallHooks(ctx context.Context, localDev bool, force bool) (int, error) {
 67→	worktreeRoot, err := paths.WorktreeRoot(ctx)
 68→	if err != nil {
 69→		worktreeRoot = "."
 70→	}
 71→
 72→	hooksPath := filepath.Join(worktreeRoot, ".kiro", hooksDir, HooksFileName)
 73→
 74→	// If hooks are already installed and not forcing, check if they're current
 75→	if !force {
 76→		if existing, readErr := os.ReadFile(hooksPath); readErr == nil { //nolint:gosec // path constructed from repo root
 77→			var file kiroAgentFile
 78→			if json.Unmarshal(existing, &file) == nil && allHooksPresent(file.Hooks, localDev) && allIDEHooksPresent(worktreeRoot, localDev) {
 79→				return 0, nil
 80→			}
 81→		}
 82→	}
 83→
 84→	cmdPrefix := hookCmdPrefix(localDev)
 85→
 86→	file := kiroAgentFile{
 87→		Name: "entire",
 88→		// Include all default Kiro tools so the agent profile doesn't restrict them.
 89→		Tools: []string{
 90→			"read", "write", "shell", "grep", "glob",
 91→			"aws", "report", "introspect", "knowledge",
 92→			"thinking", "todo", "delegate",
 93→		},
 94→		Hooks: kiroHooks{
 95→			AgentSpawn:       []kiroHookEntry{{Command: cmdPrefix + HookNameAgentSpawn}},
 96→			UserPromptSubmit: []kiroHookEntry{{Command: cmdPrefix + HookNameUserPromptSubmit}},
 97→			PreToolUse:       []kiroHookEntry{{Command: cmdPrefix + HookNamePreToolUse}},
 98→			PostToolUse:      []kiroHookEntry{{Command: cmdPrefix + HookNamePostToolUse}},
 99→			Stop:             []kiroHookEntry{{Command: cmdPrefix + HookNameStop}},
100→		},
101→	}
102→
103→	if err := os.MkdirAll(filepath.Dir(hooksPath), 0o750); err != nil {
104→		return 0, fmt.Errorf("failed to create .kiro/agents directory: %w", err)
105→	}
106→
107→	output, err := jsonutil.MarshalIndentWithNewline(file, "", "  ")
108→	if err != nil {
109→		return 0, fmt.Errorf("failed to marshal hooks config: %w", err)
110→	}
111→
112→	if err := os.WriteFile(hooksPath, output, 0o600); err != nil {
113→		return 0, fmt.Errorf("failed to write hooks config: %w", err)
114→	}
115→
116→	// Install IDE hooks (.kiro/hooks/*.kiro.hook)
117→	ideCount, err := installIDEHooks(worktreeRoot, cmdPrefix)
118→	if err != nil {
119→		return 0, fmt.Errorf("failed to install IDE hooks: %w", err)
120→	}
121→
122→	return len(k.HookNames()) + ideCount, nil
123→}
124→
125→// UninstallHooks removes the Entire hooks config file and IDE hook files.
126→func (k *KiroAgent) UninstallHooks(ctx context.Context) error {
127→	worktreeRoot, err := paths.WorktreeRoot(ctx)
128→	if err != nil {
129→		worktreeRoot = "."
130→	}
131→
132→	// Remove CLI agent file
133→	hooksPath := filepath.Join(worktreeRoot, ".kiro", hooksDir, HooksFileName)
134→	if err := os.Remove(hooksPath); err != nil && !os.IsNotExist(err) {
135→		return fmt.Errorf("failed to remove hooks config: %w", err)
136→	}
137→
138→	// Remove IDE hook files
139→	for _, def := range ideHookDefs {
140→		idePath := filepath.Join(worktreeRoot, ".kiro", ideHooksDir, def.Filename+ideHookFileSuffix)
141→		if err := os.Remove(idePath); err != nil && !os.IsNotExist(err) {
142→			return fmt.Errorf("failed to remove IDE hook %s: %w", def.Filename, err)
143→		}
144→	}
145→
146→	return nil
147→}
148→
149→// AreHooksInstalled checks if Entire hooks are installed.
150→// Returns true if EITHER CLI agent hooks or IDE hooks are present.
151→func (k *KiroAgent) AreHooksInstalled(ctx context.Context) bool {
152→	worktreeRoot, err := paths.WorktreeRoot(ctx)
153→	if err != nil {
154→		worktreeRoot = "."
155→	}
156→
157→	// Check CLI agent hooks
158→	hooksPath := filepath.Join(worktreeRoot, ".kiro", hooksDir, HooksFileName)
159→	data, err := os.ReadFile(hooksPath) //nolint:gosec // path constructed from repo root
160→	if err == nil {
161→		var file kiroAgentFile
162→		if json.Unmarshal(data, &file) == nil {
163→			if hasEntireHook(file.Hooks.AgentSpawn) ||
164→				hasEntireHook(file.Hooks.UserPromptSubmit) ||
165→				hasEntireHook(file.Hooks.Stop) {
166→				return true
167→			}
168→		}
169→	}
170→
171→	// Check IDE hooks — any Entire IDE hook file means hooks are installed
172→	return anyIDEHookPresent(worktreeRoot)
173→}
174→
175→// GetSupportedHooks returns the hook types Kiro supports.
176→func (k *KiroAgent) GetSupportedHooks() []agent.HookType {
177→	return []agent.HookType{
178→		agent.HookSessionStart,
179→		agent.HookUserPromptSubmit,
180→		agent.HookPreToolUse,
181→		agent.HookPostToolUse,
182→		agent.HookStop,
183→	}
184→}
185→
186→func allHooksPresent(hooks kiroHooks, localDev bool) bool {
187→	cmdPrefix := hookCmdPrefix(localDev)
188→
189→	return hookCommandExists(hooks.AgentSpawn, cmdPrefix+HookNameAgentSpawn) &&
190→		hookCommandExists(hooks.UserPromptSubmit, cmdPrefix+HookNameUserPromptSubmit) &&
191→		hookCommandExists(hooks.PreToolUse, cmdPrefix+HookNamePreToolUse) &&
192→		hookCommandExists(hooks.PostToolUse, cmdPrefix+HookNamePostToolUse) &&
193→		hookCommandExists(hooks.Stop, cmdPrefix+HookNameStop)
194→}
195→
196→func hookCommandExists(entries []kiroHookEntry, command string) bool {
197→	for _, entry := range entries {
198→		if entry.Command == command {
199→			return true
200→		}
201→	}
202→	return false
203→}
204→
205→func isEntireHook(command string) bool {
206→	for _, prefix := range entireHookPrefixes {
207→		if strings.HasPrefix(command, prefix) {
208→			return true
209→		}
210→	}
211→	return false
212→}
213→
214→func hasEntireHook(entries []kiroHookEntry) bool {
215→	for _, entry := range entries {
216→		if isEntireHook(entry.Command) {
217→			return true
218→		}
219→	}
220→	return false
221→}
222→
223→func hookCmdPrefix(localDev bool) string {
224→	if localDev {
225→		return localDevCmdPrefix + "hooks kiro "
226→	}
227→	return prodHookCmdPrefix
228→}
229→
230→// installIDEHooks creates .kiro/hooks/*.kiro.hook files for the Kiro IDE.
231→func installIDEHooks(worktreeRoot, cmdPrefix string) (int, error) {
232→	dir := filepath.Join(worktreeRoot, ".kiro", ideHooksDir)
233→	if err := os.MkdirAll(dir, 0o750); err != nil {
234→		return 0, fmt.Errorf("failed to create .kiro/hooks directory: %w", err)
235→	}
236→
237→	for _, def := range ideHookDefs {
238→		hook := kiroIDEHookFile{
239→			Enabled:     true,
240→			Name:        def.Filename,
241→			Description: "Entire CLI " + def.TriggerType + " hook",
242→			Version:     ideHookVersion,
243→			When: kiroIDEHookWhen{
244→				Type: def.TriggerType,
245→			},
246→			Then: kiroIDEHookThen{
247→				Type:    "runCommand",
248→				Command: cmdPrefix + def.CLIVerb,
249→			},
250→		}
251→
252→		data, err := jsonutil.MarshalIndentWithNewline(hook, "", "  ")
253→		if err != nil {
254→			return 0, fmt.Errorf("failed to marshal IDE hook %s: %w", def.Filename, err)
255→		}
256→
257→		path := filepath.Join(dir, def.Filename+ideHookFileSuffix)
258→		if err := os.WriteFile(path, data, 0o600); err != nil {
259→			return 0, fmt.Errorf("failed to write IDE hook %s: %w", def.Filename, err)
260→		}
261→	}
262→
263→	return len(ideHookDefs), nil
264→}
265→
266→// allIDEHooksPresent checks that all 4 IDE hook files exist and have correct commands.
267→func allIDEHooksPresent(worktreeRoot string, localDev bool) bool {
268→	cmdPrefix := hookCmdPrefix(localDev)
269→
270→	for _, def := range ideHookDefs {
271→		path := filepath.Join(worktreeRoot, ".kiro", ideHooksDir, def.Filename+ideHookFileSuffix)
272→		data, err := os.ReadFile(path) //nolint:gosec // path constructed from repo root
273→		if err != nil {
274→			return false
275→		}
276→		var hook kiroIDEHookFile
277→		if err := json.Unmarshal(data, &hook); err != nil {
278→			return false
279→		}
280→		if hook.Then.Command != cmdPrefix+def.CLIVerb {
281→			return false
282→		}
283→	}
284→	return true
285→}
286→
287→// anyIDEHookPresent checks if any Entire IDE hook file exists.
288→func anyIDEHookPresent(worktreeRoot string) bool {
289→	for _, def := range ideHookDefs {
290→		path := filepath.Join(worktreeRoot, ".kiro", ideHooksDir, def.Filename+ideHookFileSuffix)
291→		data, err := os.ReadFile(path) //nolint:gosec // path constructed from repo root
292→		if err != nil {
293→			continue
294→		}
295→		var hook kiroIDEHookFile
296→		if json.Unmarshal(data, &hook) == nil && isEntireIDEHook(hook) {
297→			return true
298→		}
299→	}
300→	return false
301→}
302→
303→// isEntireIDEHook checks if an IDE hook file belongs to Entire.
304→func isEntireIDEHook(hook kiroIDEHookFile) bool {
305→	return strings.HasPrefix(hook.Name, "entire-") && isEntireHook(hook.Then.Command)
306→}
