 13→func TestInstallHooks_FreshInstall(t *testing.T) {
 14→	tempDir := t.TempDir()
 15→	t.Chdir(tempDir)
 16→
 17→	ag := &KiroAgent{}
 18→	count, err := ag.InstallHooks(context.Background(), false, false)
 19→	if err != nil {
 20→		t.Fatalf("InstallHooks() error = %v", err)
 21→	}
 22→	if count != 9 {
 23→		t.Errorf("InstallHooks() returned count %d, want 9 (5 CLI + 4 IDE)", count)
 24→	}
 25→
 26→	file := readKiroAgentFile(t, tempDir)
 27→
 28→	if file.Name != "entire" {
 29→		t.Errorf("Name = %q, want %q", file.Name, "entire")
 30→	}
 31→	if len(file.Tools) == 0 {
 32→		t.Error("Tools should not be empty")
 33→	}
 34→	assertKiroHookCommand(t, file.Hooks.AgentSpawn, "entire hooks kiro agent-spawn")
 35→	assertKiroHookCommand(t, file.Hooks.UserPromptSubmit, "entire hooks kiro user-prompt-submit")
 36→	assertKiroHookCommand(t, file.Hooks.PreToolUse, "entire hooks kiro pre-tool-use")
 37→	assertKiroHookCommand(t, file.Hooks.PostToolUse, "entire hooks kiro post-tool-use")
 38→	assertKiroHookCommand(t, file.Hooks.Stop, "entire hooks kiro stop")
 39→}
