287→func TestAreHooksInstalled_AfterInstall(t *testing.T) {
288→	tempDir := t.TempDir()
289→	t.Chdir(tempDir)
290→
291→	ag := &KiroAgent{}
292→
293→	// Not installed initially
294→	if ag.AreHooksInstalled(context.Background()) {
295→		t.Error("hooks should not be installed initially")
296→	}
